//
// The ECHO hyperspace of the Hyperspace slide as a canvas element kind: a field packed with circles, each one a space
// holding a connected graph of objects on a hexagonal lattice, with dashed bridges between spaces and the objects a
// plugin shows lit in their type's colour (studio `assets/deck/lib/substrate-view.mjs`).
//
// It is the space graph packed into many circles instead of one, so each space's graph is generated by the same
// module (`components/Graph/generator/space-graph.generator.ts`) from the field's seed and the space's index.
//
// What is NOT ported, and is read from the sidecar instead: the packing (`packages/substrate/pack.mjs`) and the flow
// resolution (nearest entry, a ranked walk, a route that avoids links an earlier flow took). The sidecar records
// their output — every space's circle, and every lit object with its type and position — which is what this kind
// takes as its input. A port would replace `spaces` and `lit` with a second seed; the drawing would not change.
//

import './theme.css';

import * as Schema from 'effect/Schema';
import React from 'react';

import { type ElementKindSpec, type NodeViewProps, kindData } from '@dxos/react-ui-canvas';
import { Scene } from '@dxos/scene';

import { layout } from '../../components/Graph/generator/space-graph.generator.ts';
import { graphFields } from '../../components/Graph/index.ts';
import { TONES, toneValue } from './FeedCard.tsx';

/** A packed space, as a fraction of the field's own box so it scales with the node. */
const Space = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
  /** The radius, as a fraction of the field's width. */
  r: Schema.Number,
});

/** An object a plugin flow lights up, as a fraction of the field's box, in its type's colour. */
const Lit = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
  tone: Schema.optional(Schema.Literals(TONES)),
});

export const substrateFields = {
  ...graphFields,
  /** The packed spaces, in packing order; without them the field draws one space of its own. */
  spaces: Schema.optional(Schema.Array(Space).annotate({ title: 'Spaces' })),
  /** The objects the plugin flows reach, drawn lit. */
  lit: Schema.optional(Schema.Array(Lit).annotate({ title: 'Lit objects' })),
  /** How many of the closest pairs of spaces are bridged. */
  bridges: Schema.optional(Schema.Number.check(Schema.isInt()).annotate({ title: 'Bridges' })),
};

/** The kind's own fields, kept under `data` (decision 21). */
export const SubstrateData = Schema.Struct(substrateFields);

export const SubstrateNode = Schema.Struct({
  ...Scene.Element2D.fields,
  type: Schema.Literal('substrate'),
  data: SubstrateData,
});

const DEFAULTS = { pitch: 24, fill: 0.55, extra: 0.4, size: 24, bridges: 0 } as const;

type Circle = { x: number; y: number; r: number };

/** The `count` closest pairs of spaces, by the gap between their edges: what the field bridges. */
const bridgesOf = (spaces: readonly Circle[], count: number): [number, number][] =>
  spaces
    .flatMap((from, index) =>
      spaces.slice(index + 1).map((to, offset) => ({
        pair: [index, index + 1 + offset] as [number, number],
        gap: Math.hypot(to.x - from.x, to.y - from.y) - from.r - to.r,
      })),
    )
    .sort((left, right) => left.gap - right.gap)
    .slice(0, Math.max(0, count))
    .map(({ pair }) => pair);

/** The segment between two spaces, from edge to edge. */
const span = (from: Circle, to: Circle) => {
  const length = Math.hypot(to.x - from.x, to.y - from.y) || 1;
  const [unitX, unitY] = [(to.x - from.x) / length, (to.y - from.y) / length];
  return {
    x1: from.x + unitX * from.r,
    y1: from.y + unitY * from.r,
    x2: to.x - unitX * to.r,
    y2: to.y - unitY * to.r,
  };
};

export const SubstrateNodeView = ({ node }: NodeViewProps) => {
  const data = kindData(SubstrateData, node);
  if (!data) {
    return null;
  }

  const settings = { ...DEFAULTS, ...data };
  const { width, height } = node.size;
  // The sidecar's fractions against the node's own box, so the field moves and resizes with the node.
  const spaces: Circle[] = (
    settings.spaces ?? [{ x: 0.5, y: 0.5, r: Math.min(width, height) / 2 / Math.max(1, width) }]
  ).map(({ x, y, r }) => ({ x: x * width, y: y * height, r: r * width }));
  // Each space's own lattice, seeded by the field's seed and the space's place in the packing: one module, nine
  // scales. `layout` names the object radius `size`, which an element's own `size` (its frame) already takes.
  const graphs = spaces.map((space, index) =>
    layout({ x: space.x, y: space.y }, space.r, {
      ...settings,
      seed: settings.seed + index,
      size: settings.size,
    }),
  );
  return (
    <svg
      className='dx-cover overflow-visible'
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      data-testid='substrate-node'
    >
      {bridgesOf(spaces, settings.bridges).map((pair, index) => (
        <line
          key={`bridge-${index}`}
          {...span(spaces[pair[0]], spaces[pair[1]])}
          className='stroke-neutral-border'
          strokeWidth={1.4}
          strokeDasharray='5 5'
          opacity={0.7}
        />
      ))}
      {spaces.map((space, index) => {
        const { cells, nodes, links, nodeR } = graphs[index];
        const on = new Set(nodes.map((point) => `${point.x},${point.y}`));
        return (
          <g key={`space-${index}`} data-testid='substrate-space'>
            <circle
              cx={space.x}
              cy={space.y}
              r={space.r}
              className='fill-none stroke-neutral-border'
              strokeWidth={1.6}
            />
            {cells
              .filter((cell) => !on.has(`${cell.x},${cell.y}`))
              .map((cell, cellIndex) => (
                <circle
                  key={`cell-${cellIndex}`}
                  cx={cell.x}
                  cy={cell.y}
                  r={Math.max(1.1, nodeR * 0.3)}
                  className='fill-neutral-border'
                  opacity={0.3}
                />
              ))}
            {links.map(([from, to], linkIndex) => (
              <line
                key={`link-${linkIndex}`}
                x1={nodes[from].x}
                y1={nodes[from].y}
                x2={nodes[to].x}
                y2={nodes[to].y}
                className='stroke-neutral-border'
                strokeWidth={Math.max(1.2, nodeR * 0.32)}
                opacity={0.55}
              />
            ))}
            {nodes.map((point, objectIndex) => (
              <circle
                key={`object-${objectIndex}`}
                cx={point.x}
                cy={point.y}
                r={nodeR}
                className='fill-neutral-border'
              />
            ))}
          </g>
        );
      })}
      {/* The lit objects sit over the lattice: a plugin's own elements, in the colour of the type that holds them. */}
      {(settings.lit ?? []).map(({ x, y, tone }, index) => (
        <circle
          key={`lit-${index}`}
          cx={x * width}
          cy={y * height}
          r={(settings.pitch * settings.size) / 100 + 1.4}
          data-testid='substrate-lit'
          fill={toneValue(tone) ?? 'var(--sd-fg)'}
        />
      ))}
    </svg>
  );
};

export const substrateSpec: ElementKindSpec = {
  // Five ports a side: a true middle to tie a trunk to, and room either side of it for a fan of edges
  // that converge on one card.
  portsPerSide: 5,
  name: 'Substrate',
  icon: 'ph--circles-three--regular',
  key: 'B',
  schema: SubstrateNode,
  component: SubstrateNodeView,
  create: ({ id, z, center, size }) => ({ type: 'substrate', id, z, center, size, data: { seed: 29 } }),
  // Nominal units (one unit is the major grid cell, 48px): the deck's 812 x 820 field, give or take.
  defaultSize: { width: 17, height: 17 },
  resizable: true,
  minSize: { width: 180, height: 180 },
  // The field is the shape: the kind draws every circle it holds.
  bare: true,
};
